const mails = await api.get("/mails", { label: "환불" });
const list = Array.isArray(mails) ? mails : (mails.items || mails.data || mails.mails || []);
console.log("count:", list.length);
if (list.length) console.log("keys:", Object.keys(list[0]));
const gold = await api.get("/customers", { tier: "gold" });
const gl = Array.isArray(gold) ? gold : (gold.items || gold.data || gold.customers || []);
console.log("gold count:", gl.length);
if (gl.length) console.log("gold keys:", Object.keys(gl[0]));

const mails = await api.get("/mails", {});
const list = Array.isArray(mails) ? mails : (mails.items || mails.data || mails.mails || []);
console.log("total:", list.length);
if (list.length) console.log("keys:", Object.keys(list[0]));
const labels = [...new Set(list.map(m => m.label))];
console.log("labels:", labels);

const mails = await api.get("/mails", { label: "refund" });
const list = Array.isArray(mails) ? mails : (mails.items || mails.data || mails.mails || []);
const ids = [...new Set(list.map(m => m.customer_id).filter(Boolean))];
console.log("refund mails:", list.length, "unique customers:", ids.length);
const gold = await api.get("/customers", { tier: "gold" });
const gl = Array.isArray(gold) ? gold : (gold.items || gold.data || gold.customers || []);
const goldIds = new Set(gl.map(c => c.id));
const matches = gl.filter(c => ids.includes(c.id)).map(c => c.name);
console.log("matched gold names:", matches);
const senderGold = list.filter(m => goldIds.has(m.customer_id)).map(m => m.from_name);
console.log("sender names via mail:", [...new Set(senderGold)]);

